process_provider.text:
import os
fn answer() -> i64 {
  const first = os.getpid()
  const second = os.getpid()
  if (first <= 0 || first != second) { return 0 }
  return 1
}

clock_provider.text:
import time
fn answer() -> i64 {
  const wall = time.now()
  const monotonic = time.monotonic()
  const cpu = time.clock()
  const offset = time.localOffsetAt(0)
  if (wall <= 0) { return 0 }
  if (monotonic <= 0) { return 0 }
  if (cpu < 0) { return 0 }
  if (offset < -1440) { return 0 }
  if (offset > 1440) { return 0 }
  return 1
}

